c.python:
class Solution:
    def addRungs(self, rungs: List[int], dist: int) -> int:
        cur = added = 0
        for h in rungs:
            while h - cur > dist:
                cur += dist
                added += 1
            cur = h
        return added

c.cpp:
class Solution {
public:
    int addRungs(vector<int>& rungs, int dist) {
        long long cur = 0;
        long long added = 0;
        for (int h : rungs) {
            while (h - cur > dist) {
                cur += dist;
                added++;
            }
            cur = h;
        }
        return (int)added;
    }
};

